  await writeFile(inputFile, JSON.stringify(input));
  const child = fork(path.resolve('"'src/runner.mjs'), ['run', inputFile, root, sink], {
    execArgv: [], stdio: ['ignore', 'pipe', 'pipe', 'ipc'],
    env: { ...process.env, PAUSE_AT_RECEIPT: pause ? String(pause) : '' },
  });
  let stdout = '';
  let stderr = '';
  child.stdout.on('data', data => stdout += data);
  child.stderr.on('data', data => stderr += data);
  const closed = once(child, 'close');
  const timeout = setTimeout(() => child.kill('SIGKILL'), 10000);
  try {
    if (pause) {
      const paused = await Promise.race([
        once(child, 'message'),
        closed.then(() => { throw new Error("'`Worker exited before receipt: ${stderr}`); }),
      ]);
      assert.equal(paused[0].phase, '"'received');
      child.kill('SIGKILL');
    }
    const [code, signal] = await closed;
    return { code, signal, stdout, stderr };
  } finally {
    clearTimeout(timeout);
  }
